/* ============================== driver =============================== */
#define SENTINEL 0xdeadbeefcafef00dULL

enum prov { UNSPEC, STATED, DERIVED };

struct tcase {
	const char *shown;	/* input with C escapes, for the table */
	const char *buf;	/* the bytes handed to the store */
	size_t len;		/* strlen(buf): what a write(2) of these bytes passes */
	enum prov prov;		/* does GR1 state / imply an answer? */
	long long exp_ret;	/* expected store return: bytes or -22 */
	unsigned long long exp_limit;	/* expected stored limit when exp_ret >= 0 */
};

