static void hexbytes(const char *s, size_t n, char *out, size_t outsz)
{
	size_t i, o = 0;
	out[0] = '\0';
	for (i = 0; i < n && o + 4 < outsz; i++)
		o += (size_t)snprintf(out + o, outsz - o, "%02x ", (unsigned char)s[i]);
	if (n == 0)
		snprintf(out, outsz, "(none)");
}

static void printable(const char *s, size_t n, char *out, size_t outsz)
{
	size_t i, o = 0;
	out[0] = '\0';
	for (i = 0; i < n && o + 5 < outsz; i++) {
		unsigned char c = (unsigned char)s[i];
		if (c == '\n')      o += (size_t)snprintf(out + o, outsz - o, "\\n");
		else if (c == '\t') o += (size_t)snprintf(out + o, outsz - o, "\\t");
		else if (c == '\r') o += (size_t)snprintf(out + o, outsz - o, "\\r");
		else if (c >= 0x20 && c < 0x7f)
			o += (size_t)snprintf(out + o, outsz - o, "%c", c);
		else
			o += (size_t)snprintf(out + o, outsz - o, "\\x%02x", c);
	}
	if (n == 0)
		snprintf(out, outsz, "(empty)");
}

int main(void)
{
	size_t i, n = sizeof(cases) / sizeof(cases[0]);
	unsigned mism = 0, stated = 0, derived = 0, wrote_on_error = 0;
	char hx[256], pr[128], tail[32];

	printf("C2-2 / row GR1 harness: memparse() -> btrfs_devinfo_scrub_speed_max_store()\n");
	printf("pinned: Linux v7.2.11 lib/cmdline.c vsprintf.c kstrtox.c, include/linux/overflow.h,\n");
	printf("        lib/string_helpers.c, lib/ctype.c, include/linux/ctype.h,\n");
	printf("        fs/btrfs/sysfs.c (round-44 frozen). -EINVAL is printed as -22.\n");
	printf("columns: i | input | bytes written | len | memparse value | endptr off | byte at endptr\n");
	printf("         | store return | stored limit | how GR1 reads | match\n\n");

	for (i = 0; i < n; i++) {
		const struct tcase *c = &cases[i];
		struct btrfs_device dev;
		char *endptr = NULL;
		unsigned long long val;
		size_t epoff;
		ssize_t ret;
		unsigned char eb;
		int match = 1;
		char limitbuf[64];

		val = memparse(c->buf, &endptr);
		epoff = (size_t)(endptr - c->buf);
		eb = (unsigned char)*endptr;

		memset(&dev, 0, sizeof(dev));
		dev.scrub_speed_max = SENTINEL;
		ret = btrfs_devinfo_scrub_speed_max_store(&dev.devid_kobj, NULL, c->buf, c->len);
		if (ret < 0 && dev.scrub_speed_max != SENTINEL)
			wrote_on_error++;

		hexbytes(c->buf, c->len, hx, sizeof(hx));
		printable(c->buf, c->len, pr, sizeof(pr));
		if (eb == 0)
			snprintf(tail, sizeof(tail), "'\\0'");
		else if (eb == '\n')
			snprintf(tail, sizeof(tail), "'\\n'");
		else if (eb >= 0x20 && eb < 0x7f)
			snprintf(tail, sizeof(tail), "'%c'", eb);
		else
			snprintf(tail, sizeof(tail), "'\\x%02x'", eb);

		if (ret < 0)
			snprintf(limitbuf, sizeof(limitbuf), "-");
		else
			snprintf(limitbuf, sizeof(limitbuf), "%llu (0x%llx)",
				 dev.scrub_speed_max, dev.scrub_speed_max);

		if (c->prov == UNSPEC) {
			printf("%2zu | %-26s | %-46s | %2zu | %20llu | %2zu | %-6s | %6ld | %-28s | unspecified | -\n",
			       i, pr, hx, c->len, val, epoff, tail, (long)ret, limitbuf);
			continue;
		}
		if (c->prov == STATED)
			stated++;
		else
			derived++;
		if (ret != c->exp_ret)
			match = 0;
		if (ret >= 0 && dev.scrub_speed_max != c->exp_limit)
			match = 0;
		if (!match)
			mism++;
		printf("%2zu | %-26s | %-46s | %2zu | %20llu | %2zu | %-6s | %6ld | %-28s | %-9s | %s\n",
		       i, pr, hx, c->len, val, epoff, tail, (long)ret, limitbuf,
		       c->prov == STATED ? "stated" : "derived", match ? "ok" : "MISMATCH");
	}

	printf("\nsummary: %zu cases, %u stated + %u derived expectations checked, %u MISMATCH, "
	       "%u store-wrote-on-error\n", n, stated, derived, mism, wrote_on_error);
	return (mism || wrote_on_error) ? 1 : 0;
}
